import React, { useState, useEffect } from 'react';
import { Modal, Button, Form } from 'react-bootstrap';

export default function ProductsList() {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const [showModal, setShowModal] = useState(false);
  const [currentProduct, setCurrentProduct] = useState(null);

  const token = localStorage.getItem('token');

  const fetchProducts = async () => {
    try {
      const res = await fetch('http://localhost/api/productes', {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) throw new Error('Error al obtenir els productes');
      const data = await res.json();
      setProducts(data.dades || []);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchProducts();
  }, []);

  const handleDelete = async (id) => {
    if (!window.confirm('Segur que vols eliminar aquest producte?')) return;
    try {
      const res = await fetch(`http://localhost/api/productes/${id}`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) throw new Error('No s\'ha pogut eliminar el producte');
      fetchProducts();
    } catch (err) {
      alert(err.message);
    }
  };

  const handleEdit = (product) => {
    setCurrentProduct(product);
    setShowModal(true);
  };

  const handleSave = async () => {
    try {
      const res = await fetch(`http://localhost/api/productes/${currentProduct.id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(currentProduct),
      });
      if (!res.ok) throw new Error('Error al actualitzar el producte');
      setShowModal(false);
      fetchProducts();
    } catch (err) {
      alert(err.message);
    }
  };

  if (loading) return <p>Carregant productes...</p>;
  if (error) return <p>Error: {error}</p>;
  if (products.length === 0) return <p>No hi ha productes disponibles.</p>;

  return (
    <div className="row">
      {products.map(product => (
        <div key={product.id} className="col-md-4 mb-3">
          <div className="card h-100">
            <div className="card-body">
              <h5 className="card-title">{product.nom}</h5>
              <p className="card-text">{product.descripcio}</p>
              <p className="card-text"><strong>Referencia:</strong> {product.referencia}</p>
              <p className="card-text"><strong>Cantidad:</strong> {product.quantitat}</p>
              <Button variant="warning" onClick={() => handleEdit(product)} className="me-2">Editar</Button>
              <Button variant="danger" onClick={() => handleDelete(product.id)}>Eliminar</Button>
            </div>
          </div>
        </div>
      ))}

      <Modal show={showModal} onHide={() => setShowModal(false)}>
        <Modal.Header closeButton>
          <Modal.Title>Editar Producte</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {currentProduct && (
            <Form>
              <Form.Group className="mb-3">
                <Form.Label>Nom</Form.Label>
                <Form.Control
                  type="text"
                  value={currentProduct.nom}
                  onChange={e => setCurrentProduct({ ...currentProduct, nom: e.target.value })}
                />
              </Form.Group>
              <Form.Group className="mb-3">
                <Form.Label>Referència</Form.Label>
                <Form.Control
                  type="text"
                  value={currentProduct.referencia}
                  onChange={e => setCurrentProduct({ ...currentProduct, referencia: e.target.value })}
                />
              </Form.Group>
              <Form.Group className="mb-3">
                <Form.Label>Quantitat</Form.Label>
                <Form.Control
                  type="number"
                  value={currentProduct.quantitat}
                  onChange={e => setCurrentProduct({ ...currentProduct, quantitat: e.target.value })}
                />
              </Form.Group>
              <Form.Group className="mb-3">
                <Form.Label>Descripció</Form.Label>
                <Form.Control
                  as="textarea"
                  value={currentProduct.descripcio}
                  onChange={e => setCurrentProduct({ ...currentProduct, descripcio: e.target.value })}
                />
              </Form.Group>
            </Form>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowModal(false)}>Cancel·lar</Button>
          <Button variant="primary" onClick={handleSave}>Guardar</Button>
        </Modal.Footer>
      </Modal>
    </div>
  );
}
